import { useEffect, useMemo, useState } from 'react';
import { Copy, Download, GitCompareArrows, X } from 'lucide-react';
import { compareExternalDietPlanVersions, downloadExternalDietPlanVersion, duplicateExternalDietPlanVersion, getExternalDietPlanHistory, getExternalDietPlanVersion } from '../../lib/fiteatsyConsultantsApi';
import { validateExternalDietOption } from '../../lib/externalDietPlanPresentation.mjs';

const date=(value)=>value?new Date(value).toLocaleDateString('en-IN',{day:'2-digit',month:'short',year:'numeric'}):'Not published';
const label=(value)=>String(value||'').replaceAll('_',' ');
const downloadBlob=({blob,filename})=>{const url=URL.createObjectURL(blob);const anchor=document.createElement('a');anchor.href=url;anchor.download=filename;anchor.click();URL.revokeObjectURL(url);};

export default function ExternalDietPlanHistory({clientId,onDraftCreated,onError}){
  const [state,setState]=useState({plan:null,versions:[]});const [loading,setLoading]=useState(true);const [view,setView]=useState(null);const [compare,setCompare]=useState(null);const [selected,setSelected]=useState([]);const [busy,setBusy]=useState('');
  const load=async()=>{setLoading(true);try{setState(await getExternalDietPlanHistory(clientId));}catch(error){onError(error.message||'Unable to load Diet Plan history.');}finally{setLoading(false);}};
  useEffect(()=>{void load();},[clientId]);
  const current=useMemo(()=>state.versions.find(item=>item.number===state.plan?.currentVersion),[state]);
  const published=useMemo(()=>state.versions.find(item=>item.number===state.plan?.publishedVersion),[state]);
  const historical=state.versions.filter(item=>item.id!==current?.id&&item.id!==published?.id);
  const open=async(version)=>{setBusy(`view-${version.id}`);try{setView((await getExternalDietPlanVersion(clientId,version.id)).version);}catch(error){onError(error.message||'Unable to open historical version.');}finally{setBusy('');}};
  const exportVersion=async(version)=>{setBusy(`download-${version.id}`);try{downloadBlob(await downloadExternalDietPlanVersion(clientId,version.id));}catch(error){onError(error.message||'Unable to download historical DOCX.');}finally{setBusy('');}};
  const duplicate=async(version)=>{if(!window.confirm(`Use immutable Version ${version.number} as a new editable draft?`))return;setBusy(`duplicate-${version.id}`);try{await duplicateExternalDietPlanVersion(clientId,version.id);await load();await onDraftCreated();}catch(error){onError(error.message||'Unable to create a new draft.');}finally{setBusy('');}};
  const runCompare=async()=>{if(selected.length!==2)return;setBusy('compare');try{setCompare(await compareExternalDietPlanVersions(clientId,selected[1],selected[0]));}catch(error){onError(error.message||'Unable to compare versions.');}finally{setBusy('');}};
  if(loading)return <section className="rounded-2xl border border-slate-200 bg-white p-6 text-sm text-slate-500">Loading version history…</section>;
  if(!state.plan)return null;
  const card=(version,title)=>version?<article className="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm"><div className="flex flex-wrap items-start justify-between gap-3"><div><p className="text-xs font-bold uppercase tracking-wider text-blue-700">{title}</p><h4 className="mt-1 text-lg font-bold">Version {version.number}</h4><p className="mt-1 text-sm text-slate-500">{label(version.status)} · {version.plan?.dailyTargets?.calories??'—'} kcal · {version.plan?.dailyTargets?.protein??'—'} g protein</p><p className="mt-1 text-xs text-slate-400">Created {date(version.createdAt)} · Published {date(version.publishedAt)}</p></div><label className="flex items-center gap-2 text-xs font-semibold"><input type="checkbox" checked={selected.includes(version.id)} disabled={!selected.includes(version.id)&&selected.length>=2} onChange={()=>setSelected(values=>values.includes(version.id)?values.filter(id=>id!==version.id):[...values,version.id])}/>Compare</label></div><div className="mt-4 flex flex-wrap gap-2"><button onClick={()=>open(version)} className="rounded-lg border px-3 py-2 text-xs font-semibold">View Published Plan</button><button onClick={()=>exportVersion(version)} disabled={Boolean(busy)} className="inline-flex items-center gap-1 rounded-lg border px-3 py-2 text-xs font-semibold"><Download size={13}/>DOCX</button><button onClick={()=>duplicate(version)} disabled={Boolean(busy)} className="inline-flex items-center gap-1 rounded-lg bg-slate-950 px-3 py-2 text-xs font-semibold text-white"><Copy size={13}/>Create Revision</button></div></article>:null;
  return <section className="space-y-4"><div className="flex flex-wrap items-center justify-between gap-3"><div><h3 className="text-xl font-bold">Diet Plan history</h3><p className="mt-1 text-sm text-slate-500">Immutable snapshots preserve exact foods, servings and nutrition values.</p></div><button onClick={runCompare} disabled={selected.length!==2||Boolean(busy)} className="inline-flex min-h-10 items-center gap-2 rounded-xl bg-blue-700 px-4 text-sm font-bold text-white disabled:opacity-40"><GitCompareArrows size={16}/>Compare selected</button></div><div className="grid gap-4 lg:grid-cols-2">{card(published,'Current published plan')}{current?.id!==published?.id&&card(current,'Current draft')}</div>{historical.length>0&&<div><h4 className="mb-3 font-bold">Historical plans</h4><div className="grid gap-4 lg:grid-cols-2">{historical.map(version=><div key={version.id}>{card(version,'Historical version')}</div>)}</div></div>}{view&&<SnapshotDrawer version={view} onClose={()=>setView(null)}/>} {compare&&<CompareDrawer comparison={compare} onClose={()=>setCompare(null)}/>}</section>;
}

function SnapshotDrawer({version,onClose}){return <div className="fixed inset-0 z-50 flex justify-end bg-slate-950/40" role="dialog" aria-modal="true"><section className="h-full w-full max-w-3xl overflow-y-auto bg-white p-5 shadow-2xl sm:p-8"><div className="flex items-start justify-between"><div><p className="text-xs font-bold uppercase tracking-wider text-blue-700">Immutable historical snapshot</p><h3 className="mt-1 text-2xl font-bold">Version {version.number}</h3></div><button aria-label="Close snapshot" onClick={onClose} className="rounded-lg border p-2"><X size={18}/></button></div><div className="mt-6 space-y-5">{(version.plan?.meals||[]).map(meal=><section key={meal.mealHead}><h4 className="font-bold">{label(meal.mealHead)}</h4><div className="mt-2 grid gap-2 sm:grid-cols-2">{meal.options.map(option=>{const item=validateExternalDietOption(option);return <article key={option.combinationId} className="rounded-xl bg-slate-50 p-3"><p className="font-semibold">{item.title}</p><p className="mt-1 text-xs text-slate-500">{item.serving||'Serving preserved'} · {Math.round(item.nutrition.kcal||0)} kcal</p></article>})}</div></section>)}</div></section></div>}
function CompareDrawer({comparison,onClose}){const rows=[['Calories',comparison.targets.calories],['Protein',comparison.targets.protein]];const changes=[['Added',comparison.options.added,'bg-emerald-50'],['Removed',comparison.options.removed,'bg-red-50'],['Changed',comparison.options.changed,'bg-amber-50']];return <div className="fixed inset-0 z-50 flex justify-end bg-slate-950/40" role="dialog" aria-modal="true"><section className="h-full w-full max-w-xl overflow-y-auto bg-white p-5 shadow-2xl sm:p-8"><div className="flex justify-between"><div><p className="text-xs font-bold uppercase tracking-wider text-blue-700">Plan comparison</p><h3 className="mt-1 text-2xl font-bold">Version {comparison.from.number} → {comparison.to.number}</h3></div><button aria-label="Close comparison" onClick={onClose} className="rounded-lg border p-2"><X size={18}/></button></div><div className="mt-6 grid gap-3">{rows.map(([name,value])=><div key={name} className="grid grid-cols-3 rounded-xl bg-slate-50 p-4 text-sm"><strong>{name}</strong><span>{value.from??'—'}</span><span>{value.to??'—'}</span></div>)}</div><div className="mt-6 grid gap-3 sm:grid-cols-3">{changes.map(([name,items,tone])=><section key={name} className={`rounded-xl p-4 ${tone}`}><p className="font-bold">{name}</p><p className="mt-1 text-2xl font-bold">{items.length}</p><p className="text-xs text-slate-500">food or serving options</p></section>)}</div></section></div>}
